// Calculate the cofactor of a 3x3 matrix at position (row, col)
// Cofactor = (-1)^(row+col) * determinant of 2x2 submatrix

// Extract the 2x2 submatrix elements (excluding the specified row and column)
double a = m[(row + 1) % 3][(col + 1) % 3];
double b = m[(row + 1) % 3][(col + 2) % 3];
double c = m[(row + 2) % 3][(col + 1) % 3];
double d = m[(row + 2) % 3][(col + 2) % 3];

// Calculate determinant of the 2x2 submatrix
double det = a * d - b * c;

// Apply the cofactor sign: (-1)^(row+col)
// If row+col is even, sign is +1; if odd, sign is -1
double sign = ((row + col) % 2 == 0) ? 1.0 : -1.0;

return sign * det; // END_CODE

